import{_ as t,o as e,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-06","description":"","frontmatter":{"date":"2026-07-06T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-06-uxtrend.md","filePath":"daily/2026-07-06-uxtrend.md"}'),o={name:"daily/2026-07-06-uxtrend.md"};function s(i,r,g,p,h,l){return e(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="设计趋势-2026-07-06" tabindex="-1">设计趋势 - 2026-07-06 <a class="header-anchor" href="#设计趋势-2026-07-06" aria-label="Permalink to &quot;设计趋势 - 2026-07-06&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于代理UX设计和AI技术在设计工作流程中的应用。代理UX设计强调创造新型人机交互体验，而AI技术显著提升了设计流程的速度和协作性。最值得关注的是代理性用户体验对设计认知的改变，以及AI代理工作流设计模式的探讨。</p><hr><h3 id="_1-代理ux设计" tabindex="-1">1. 代理UX设计 <a class="header-anchor" href="#_1-代理ux设计" aria-label="Permalink to &quot;1. 代理UX设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨设计原则，以创造与数字设备的新类型用户体验。</p><p><strong>能解决什么问题</strong>: 如何以人为中心，设计出与AI驱动的代理系统相融合的用户体验。</p><p><strong>产品应用</strong>: 可以应用于实际产品，通过遵循设计原则，加速开发以人为本的代理系统。</p><p><strong>示例场景</strong>: 使用代理系统协助团队协作和问题解决。</p><hr><h3 id="_2-代理性用户体验将改变你对设计的所有认知" tabindex="-1">2. 代理性用户体验将改变你对设计的所有认知 <a class="header-anchor" href="#_2-代理性用户体验将改变你对设计的所有认知" aria-label="Permalink to &quot;2. 代理性用户体验将改变你对设计的所有认知&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理性用户体验强调人机之间的信任协调，而非屏幕和流程。</p><p><strong>能解决什么问题</strong>: 如何设计智能系统以确保用户感到被支持、控制和信任。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，通过提供明确的行动建议和控制方式。</p><p><strong>示例场景</strong>: 金融代理在标记可疑交易时需人类审批才能冻结账户。</p><hr><h3 id="_3-ai如何改变我的设计工作流程" tabindex="-1">3. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_3-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;3. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI技术提升了设计流程的速度和协作性，减少了猜测时间。</p><p><strong>能解决什么问题</strong>: 设计过程中从研究到原型的转换耗时且容易失去上下文。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI工具快速迭代原型和代码。</p><p><strong>示例场景</strong>: 设计师使用Figma和Cursor快速迭代原型，加速产品开发。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理和执行任务。</p><p><strong>产品应用</strong>: 可应用于实际产品，通过灵活的工作流编排不同任务。</p><p><strong>示例场景</strong>: 基于LLM的AI代理利用工具解决问题和执行计划。</p><hr><h3 id="_5-代理式用户体验-设计智能代理系统的7个原则" tabindex="-1">5. 代理式用户体验：设计智能代理系统的7个原则 <a class="header-anchor" href="#_5-代理式用户体验-设计智能代理系统的7个原则" aria-label="Permalink to &quot;5. 代理式用户体验：设计智能代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理式用户体验时，应将上下文视为共享界面，确保信息双向流通。</p><p><strong>能解决什么问题</strong>: 解决智能代理在用户界面中融入困难，导致体验脱节的问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助用户完成任务的产品，如客户服务和自动化工作流程。</p><p><strong>示例场景</strong>: 智能客服在用户浏览产品页面时提供即时帮助。</p><hr><h3 id="_6-ai在设计中的应用-改变我们的创造方式" tabindex="-1">6. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_6-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;6. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create | Figma</a></p><p><strong>一句话摘要</strong>: AI正在改变设计流程，使工作更适应性和团队协作更紧密。</p><p><strong>能解决什么问题</strong>: 解决设计任务自动化和个性化界面创建的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI预测设计需求，提高效率。</p><p><strong>示例场景</strong>: 使用AI设计工具根据用户行为定制界面。</p><hr><h3 id="_7-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">7. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_7-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;7. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI之间的信任关系。</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI功能。</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等。</p><p><strong>示例场景</strong>: 聊天机器人中提供调整响应方式的选项。</p><hr><h3 id="_8-ai-ux设计模式-人工智能带来的新交互" tabindex="-1">8. AI UX设计模式：人工智能带来的新交互 <a class="header-anchor" href="#_8-ai-ux设计模式-人工智能带来的新交互" aria-label="Permalink to &quot;8. AI UX设计模式：人工智能带来的新交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: 探索适用于成功AI体验的关键交互模式</p><p><strong>能解决什么问题</strong>: 帮助设计师在AI产品中做出更好的UX决策</p><p><strong>产品应用</strong>: 可以应用到AI产品中，通过评估模式适应性</p><p><strong>示例场景</strong>: 设计一个使用AI助手的聊天界面</p><hr><h3 id="_9-在cursor中使用ai可读设计系统进行设计" tabindex="-1">9. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_9-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;9. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: AI直接根据产品需求和UX规范生成完整产品流程。</p><p><strong>能解决什么问题</strong>: 提高设计效率，确保设计遵循统一的设计系统。</p><p><strong>产品应用</strong>: 适用于产品设计初期，将需求和规范转化为可执行原型。</p><p><strong>示例场景</strong>: 设计师将产品需求输入Cursor生成原型。</p><hr><h3 id="_10-为代理性用户体验设计指南" tabindex="-1">10. 为代理性用户体验设计指南 <a class="header-anchor" href="#_10-为代理性用户体验设计指南" aria-label="Permalink to &quot;10. 为代理性用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理性用户体验需要考虑持续性循环和用户目标。</p><p><strong>能解决什么问题</strong>: 解决用户在数字环境中快速完成任务和预测未来需求的问题。</p><p><strong>产品应用</strong>: 可以应用到智能助手和自动化服务中，通过感知、思考、行动循环来预测用户需求。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐可能感兴趣的内容。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
